-- de 공식 계정(pinwith_de)·예시 계정·예시 리스트 4개. 먼저 seed_lang_loader.sql을 실행해 둘 것.
select private.seed_lang_examples('de', 'de', $doc${"official":{"display_name":"PinWith Offiziell","bio":"Listen, die das PinWith-Team für dich zusammengestellt hat."},"samples":[{"display_name":"Beispielnutzer 1","bio":"Beispielkonto von PinWith, das zeigt, wie Freunde gemeinsam eine Reise planen."},{"display_name":"Beispielnutzer 2","bio":"Beispielkonto von PinWith, das zeigt, wie Freunde gemeinsam eine Reise planen."},{"display_name":"Beispielnutzer 3","bio":"Beispielkonto von PinWith, das zeigt, wie Freunde gemeinsam eine Reise planen."}],"lists":[{"role":"plain","owner":"official","slug":"berlin-zwei-tage-klassiker","kind":"course","title":"Berlin in 2 Tagen: Mauer, Museen, Mitte","desc":"Der Klassiker für dein erstes Berlin-Wochenende: Tag 1 rund um Brandenburger Tor und Museumsinsel, Tag 2 auf den Spuren der Mauer. Alles gut mit S- und U-Bahn verbunden.","themes":["Berlin","Städtetrip","Geschichte","Museen","Wochenende"],"sections":[{"name":"Tag 1: Mitte & Museen","by":"official","items":[{"place_id":"ChIJiQnyVcZRqEcRY0xnhE77uyY","title":"Brandenburger Tor","memo":"Komm früh morgens, dann hast du den Pariser Platz fast für dich allein. Danach sind es nur ein paar Schritte zum Reichstag.","tags":["Wahrzeichen","Fotospot"],"lat":52.516275,"lng":13.377704},{"place_id":"ChIJb204PslRqEcRKtM9yagnzCQ","title":"Mauerstücke am Potsdamer Platz","memo":"Direkt am Bahnhofsausgang stehen originale Mauersegmente mit Infotafeln – ein guter erster Eindruck, wie mitten durch die Stadt die Grenze lief.","tags":["Mauer","Kurzstopp"],"lat":52.509885,"lng":13.376233},{"place_id":"ChIJc3DkFbRRqEcRrUuZhztJVVg","title":"Gemäldegalerie","memo":"Alte Meister von Rembrandt bis Caravaggio, oft angenehm leer. Plan mindestens zwei Stunden ein – die Säle sind riesig.","tags":["Kunst","Regenwetter"],"lat":52.508498,"lng":13.365175},{"place_id":"ChIJM28dat1RqEcRC0AVNUpwAuk","title":"Alte Nationalgalerie","memo":"Auf der Museumsinsel, mit Caspar David Friedrich und den Impressionisten. Die Kolonnaden davor sind abends schön zum Sitzen.","tags":["Kunst","Museumsinsel"],"lat":52.52081,"lng":13.398353}]},{"name":"Tag 2: Auf den Spuren der Mauer","by":"official","items":[{"place_id":"ChIJZ0KxF_JRqEcRrLHB-4r-U-o","title":"Gedenkstätte Berliner Mauer","memo":"An der Bernauer Straße siehst du den Grenzstreifen noch im Originalzustand. Steig unbedingt auf den Aussichtsturm im Dokumentationszentrum.","tags":["Geschichte","Kostenlos"],"lat":52.535052,"lng":13.39019},{"place_id":"ChIJS6_t9aZHqEcRGCiRSnvpm94","title":"East Side Gallery","memo":"Das längste erhaltene Mauerstück, bemalt von Künstlern aus aller Welt. Lauf von Ostbahnhof Richtung Oberbaumbrücke, dann endest du direkt in Kreuzberg.","tags":["Street Art","Spaziergang"],"lat":52.505022,"lng":13.439695},{"place_id":"ChIJO8pczFFOqEcRLvo9iiZJnM4","title":"Das Mauermuseum an der East Side Gallery","memo":"Gut für einen Regentag oder wenn du die Geschichte hinter den Bildern verstehen willst – liegt direkt an der Strecke.","tags":["Museum","Regenwetter"],"lat":52.502656,"lng":13.445264}]}],"comments":[]},{"role":"creator","owner":"official","slug":"vlog-bayerische-alpen-neuschwanstein","kind":"course","title":"[Vlog] Bayerische Alpen: Neuschwanstein & Partnachklamm","desc":"Mein Roadtrip von München in die Berge – Märchenschloss, tosende Klamm und zum Schluss eine Maß im Biergarten. Mit allen Drehorten und den besten Uhrzeiten für Fotos.","themes":["Vlog","Bayern","Alpen","Roadtrip","Fotospots"],"sections":[{"name":"Start in München","by":"official","items":[{"place_id":"ChIJH0ui7op1nkcRQsQpsrdqAyA","title":"Biergarten am Viktualienmarkt","memo":"Im Video ganz am Anfang: Brezn und Weißwurst zum Frühstück, bevor's losgeht. Vormittags ist das Licht zwischen den Ständen super weich.","tags":["Frühstück","B-Roll"],"lat":48.135269,"lng":11.576402}]},{"name":"Allgäu: Schlösser","by":"official","items":[{"place_id":"ChIJXaNOxMr3nEcRo7ud02uGpsg","title":"Schloss Neuschwanstein","memo":"Der Drohnen-Look geht nicht (Drohnenverbot!), aber von der Marienbrücke bekommst du den Postkartenblick. Tickets unbedingt vorab online reservieren und für die Brücke früh am Morgen da sein.","tags":["Fotospot","Vorher buchen"],"lat":47.557574,"lng":10.7498},{"place_id":"ChIJh24YuUn2nEcRGNZJt6DvLDE","title":"Schloss Hohenschwangau","memo":"Das gelbe Schloss gegenüber wird oft übersehen – dabei ist der Blick vom Alpsee mit Hohenschwangau im Hintergrund mein Lieblingsshot im ganzen Video. Am besten am späten Nachmittag.","tags":["Golden Hour","Alpsee"],"lat":47.555674,"lng":10.73638}]},{"name":"Werdenfelser Land & zurück","by":"official","items":[{"place_id":"ChIJOUFSRI8GnUcRZncn4ALFq0A","title":"Partnachklamm","memo":"Im Video bei 6:40 seht ihr, wie nass es wird: Regenjacke mitnehmen und Kamera schützen. Für Aufnahmen ohne Gegenverkehr am besten gleich zur Öffnung kommen.","tags":["Wandern","Regenjacke"],"lat":47.467561,"lng":11.120027},{"place_id":"ChIJe8ga9v11nkcRX8CtPNbgTJs","title":"Augustiner-Keller","memo":"Das Ende vom Vlog: Maß unter Kastanien nach dem langen Tag. Wenn die Lichterketten angehen, gibt's die gemütlichsten Shots.","tags":["Biergarten","Abendstimmung"],"lat":48.143352,"lng":11.551979}]}],"comments":[]},{"role":"friends","owner":"ex1","slug":"rom-vier-tage-zu-dritt","kind":"collection","title":"Rom zu dritt: 4 Tage, viel Pasta","desc":"Wir drei planen unseren Rom-Trip: Jeder hat seine Must-sees eingetragen, und in den Kommentaren diskutieren wir die Route. Den finalen Plan findest du in den Kommentaren bei Trastevere.","themes":["Rom","Freunde","Italien","Pasta","Städtetrip"],"sections":[{"name":"Antikes Rom (Beispielnutzer 1)","by":"ex1","items":[{"place_id":"ChIJrRMgU7ZhLxMRxAOFkC7I8Sg","title":"Kolosseum","memo":"Zeitfenster-Tickets online holen, das Kombiticket gilt auch fürs Forum. Vor Ort sind die Schlangen sonst lang.","tags":["Must-see","Vorher buchen"],"lat":41.89021,"lng":12.492231},{"place_id":"ChIJ782pg7NhLxMR5n3swAdAkfo","title":"Forum Romanum","memo":"Kaum Schatten – Wasserflasche mitnehmen, an den Trinkbrunnen kann man nachfüllen.","tags":["Antike","Sonnenschutz"],"lat":41.892091,"lng":12.486438},{"place_id":"ChIJKzc56rhhLxMRdFBoVnQeLEk","title":"Pasqualino al Colosseo","memo":"Klassische römische Trattoria in Laufweite zum Kolosseum, perfekt fürs Mittagessen nach der Besichtigung.","tags":["Trattoria","Mittag"],"lat":41.889343,"lng":12.495223}]},{"name":"Centro Storico (Beispielnutzer 2)","by":"ex2","items":[{"place_id":"ChIJqUCGZ09gLxMRLM42IPpl0co","title":"Pantheon","memo":"Mittags fällt das Licht durch die Kuppelöffnung – sehr beeindruckend. Inzwischen braucht man ein Ticket.","tags":["Architektur"],"lat":41.898611,"lng":12.476873},{"place_id":"ChIJ1UCDJ1NgLxMRtrsCzOHxdvY","title":"Trevi-Brunnen","memo":"Tagsüber total voll, frühmorgens oder spät abends viel entspannter. Münze über die Schulter werfen nicht vergessen!","tags":["Fotospot","Früh hin"],"lat":41.900933,"lng":12.483313},{"place_id":"ChIJAfCPkKxhLxMRT0oR-jxDMvE","title":"Al Gallinaccio","memo":"Gelato ganz in der Nähe vom Trevi-Brunnen – ideal als Belohnung nach dem Gedränge.","tags":["Gelato","Snack"],"lat":41.902293,"lng":12.485695},{"place_id":"ChIJ4T6-zEhgLxMRSa1VL3N0DyY","title":"Roscioli Salumeria","memo":"Angeblich eine der besten Carbonaras der Stadt. Abends unbedingt reservieren.","tags":["Carbonara","Reservieren"],"lat":41.894256,"lng":12.474242}]},{"name":"Vatikan & Trastevere (Beispielnutzer 3)","by":"ex3","items":[{"place_id":"ChIJKcGbg2NgLxMRthZkUqDs4M8","title":"Vatikan","memo":"Für die Vatikanischen Museen online buchen, und an die Kleiderordnung für den Petersdom denken: Schultern und Knie bedeckt.","tags":["Must-see","Kleiderordnung"],"lat":41.906488,"lng":12.453641},{"place_id":"ChIJvQkTKlZgLxMRf4EdqLk_g0o","title":"Borghiciana","memo":"Frische handgemachte Pasta im Borgo Pio, nur ein paar Minuten vom Petersplatz.","tags":["Pasta","Günstig"],"lat":41.903726,"lng":12.46222},{"place_id":"ChIJ921caWhgLxMRM_bfeCcgn6M","title":"Trastevere","memo":"Kopfsteinpflaster, Efeu und Aperitivo – am schönsten ab dem späten Nachmittag zum Bummeln.","tags":["Abends","Viertel"],"lat":41.884829,"lng":12.470402}]}],"comments":[{"place_id":"ChIJrRMgU7ZhLxMRxAOFkC7I8Sg","by":"ex1","body":"Kolosseum gleich am ersten Morgen? Im Sommer wird's ab Mittag echt heiß da drin.","replies":[{"by":"ex2","body":"Ja, erster Slot am Morgen! Danach Forum und dann ab in den Schatten zum Mittagessen."},{"by":"ex3","body":"Dann buche ich jetzt gleich die Tickets, die frühen Slots sind schnell weg."}]},{"place_id":"ChIJKcGbg2NgLxMRthZkUqDs4M8","by":"ex3","body":"Vatikan dauert locker einen halben Tag. Lieber Mittwoch vormittags vermeiden, da ist Generalaudienz und alles voll.","replies":[{"by":"ex1","body":"Guter Punkt. Dann Donnerstag, und mittags direkt rüber zur Borghiciana."}]},{"place_id":"ChIJ4T6-zEhgLxMRSa1VL3N0DyY","by":"ex2","body":"Roscioli ist nicht ganz billig. Wollen wir das als unser einziges 'großes' Abendessen machen und sonst günstiger essen?","replies":[{"by":"ex3","body":"Bin dabei. Mittags Pasta to go oder Trattoria, abends einmal richtig gut."},{"by":"ex1","body":"Ich reserviere für Samstagabend, dann haben wir was zum Freuen."}]},{"place_id":"ChIJ1UCDJ1NgLxMRtrsCzOHxdvY","by":"ex2","body":"Trevi am Abend nach dem Pantheon? Beides ist nur ein Spaziergang voneinander entfernt.","replies":[{"by":"ex1","body":"Abends ist es aber auch rappelvoll. Ich wäre für frühmorgens, falls ihr's schafft 😅"},{"by":"ex3","body":"Kompromiss: Pantheon mittags, Trevi danach, und dann Eis bei Al Gallinaccio."}]},{"place_id":"ChIJ921caWhgLxMRM_bfeCcgn6M","by":"ex1","body":"Finaler Plan! Tag 1: Kolosseum + Forum, Mittag bei Pasqualino. Tag 2: Pantheon, Trevi, Gelato, abends Roscioli. Tag 3: Vatikan, Mittag Borghiciana, abends Trastevere. Tag 4: freier Vormittag, dann Flughafen. Passt das?","replies":[{"by":"ex2","body":"Perfekt! Wenn's an einem Tag regnet, tauschen wir einfach Vatikan und Pantheon."},{"by":"ex3","body":"Abgemacht. Wir laufen fast alles zu Fuß, also bequeme Schuhe einpacken!"}]}]},{"role":"food","owner":"official","slug":"muenchen-bierhallen-viktualienmarkt","kind":"collection","title":"München: Bierhallen, Wirtshäuser & Viktualienmarkt","desc":"Wo du in der Münchner Altstadt richtig bayerisch isst und trinkst – von der großen Bierhalle bis zum Biergarten unter Kastanien.","themes":["München","Bayerisch","Bier","Biergarten","Wirtshaus"],"sections":[{"name":"Große Bierhallen","by":"official","items":[{"place_id":"ChIJxfxSz4t1nkcRLxq9ze1wwak","title":"Hofbräuhaus","memo":"Touristisch, aber einmal muss man's erlebt haben: Blasmusik, lange Tische, Maßkrüge. Setz dich einfach dazu, wo Platz ist – außer an die Stammtische.","tags":["Klassiker","Blasmusik"],"lat":48.137637,"lng":11.579749},{"place_id":"ChIJSfYmtAF2nkcRpgor2WXWNYg","title":"Augustiner Stammhaus","memo":"In der Fußgängerzone, mit schönem Gewölbe und Augustiner-Bier – viele Münchner finden es authentischer als das Hofbräuhaus.","tags":["Augustiner","Altstadt"],"lat":48.1384,"lng":11.568843},{"place_id":"ChIJWSpmWop1nkcRZSRCDS-wOeU","title":"Weisses Bräuhaus","memo":"Die Adresse für Weißbier und Weißwurst. Weißwürste isst man traditionell vor Mittag, mit süßem Senf und Brezn.","tags":["Weißbier","Weißwurst"],"lat":48.136423,"lng":11.578467}]},{"name":"Rund um den Viktualienmarkt","by":"official","items":[{"place_id":"ChIJH0ui7op1nkcRQsQpsrdqAyA","title":"Biergarten am Viktualienmarkt","memo":"Hier wechselt das ausgeschenkte Bier regelmäßig zwischen den Münchner Brauereien. Brotzeit von den Marktständen ringsum ist erlaubt.","tags":["Biergarten","Brotzeit"],"lat":48.135269,"lng":11.576402},{"place_id":"ChIJccSCl4p1nkcRzQDgOnxwKdA","title":"Der Pschorr","memo":"Bier frisch aus dem Holzfass, und das Fleisch kommt von bayerischen Weiderindern – bestell den Schweinebraten.","tags":["Holzfass","Braten"],"lat":48.134816,"lng":11.575153},{"place_id":"ChIJ3ajzh4p1nkcRNo1cpcqDpO4","title":"Zum Alten Markt","memo":"Kleines, holzvertäfeltes Wirtshaus mit hausgemachter bayerischer Küche – gemütlicher als die großen Hallen, daher abends lieber reservieren.","tags":["Gemütlich","Reservieren"],"lat":48.13533,"lng":11.57765},{"place_id":"ChIJ0dAODmDfnUcRj9XljXyikUk","title":"Zum Straubinger","memo":"Bodenständiges Wirtshaus am Rand des Marktes, gut für Knödel und Tagesgerichte zu fairen Preisen.","tags":["Bodenständig"],"lat":48.133834,"lng":11.574409}]},{"name":"Biergarten","by":"official","items":[{"place_id":"ChIJe8ga9v11nkcRX8CtPNbgTJs","title":"Augustiner-Keller","memo":"Einer der schönsten Biergärten der Stadt, nah am Hauptbahnhof. Im Selbstbedienungsbereich darfst du deine eigene Brotzeit mitbringen.","tags":["Biergarten","Kastanien"],"lat":48.143352,"lng":11.551979}]}],"comments":[]}]}$doc$::jsonb);
